/* ============================================================
   VOLTA STUDIO — Design System
   Minimal, editorial, warm
   ============================================================ */

/* ── 1. Tokens (Primitive + Semantic) ─────────────────────── */
:root {
  /* Colors — warm editorial palette in OKLCH */
  --bg-body: oklch(96.5% 0.012 75);
  --bg-surface: oklch(98% 0.008 75);
  --text-primary: oklch(18% 0.02 75);
  --text-secondary: oklch(45% 0.04 75);
  --text-muted: oklch(55% 0.03 75);
  --accent-warm: oklch(60% 0.12 45);
  --accent-sage: oklch(72% 0.08 145);
  --accent-sand: oklch(78% 0.1 85);
  --accent-terracotta: oklch(58% 0.14 45);
  --border-subtle: oklch(85% 0.02 75);

  /* Typography */
  --font-serif: "Playfair Display", Georgia, "Times New Roman", serif;
  --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;

  /* Fluid type scale (Minor Third → Major Third) */
  --text-xs: clamp(0.75rem, 0.7rem + 0.25vw, 0.875rem);
  --text-sm: clamp(0.875rem, 0.8rem + 0.35vw, 1rem);
  --text-base: clamp(1rem, 0.875rem + 0.5vw, 1.125rem);
  --text-lg: clamp(1.125rem, 0.95rem + 0.75vw, 1.35rem);
  --text-xl: clamp(1.35rem, 1.05rem + 1.2vw, 1.75rem);
  --text-2xl: clamp(1.75rem, 1.2rem + 2vw, 2.5rem);
  --text-3xl: clamp(2.5rem, 1.5rem + 3.5vw, 4rem);
  --text-4xl: clamp(3.5rem, 2rem + 5vw, 6rem);
  --text-5xl: clamp(5rem, 3rem + 7vw, 10rem);

  /* Spacing scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;
  --space-40: 10rem;

  /* Layout */
  --max-width: 1400px;
  --content-width: 72ch;
  --page-gutter: clamp(1.5rem, 5vw, 4rem);

  /* Motion */
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast: 200ms;
  --duration-base: 300ms;
  --duration-slow: 500ms;
}

/* ── 2. Reset & Base ──────────────────────────────────────── */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-body);
}

img, picture, video, canvas, svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

/* ── 3. Typography ────────────────────────────────────────── */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

h1 { font-size: var(--text-4xl); }
h2 { font-size: var(--text-3xl); }
h3 { font-size: var(--text-2xl); }
h4 { font-size: var(--text-xl); }

p {
  line-height: 1.7;
  color: var(--text-secondary);
}

/* ── 4. Layout Utilities ──────────────────────────────────── */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--page-gutter);
}

.prose {
  max-width: var(--content-width);
  margin-inline: auto;
}

/* ── 5. Header & Navigation ───────────────────────────────── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: var(--space-6) var(--page-gutter);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: transparent;
  transition: background var(--duration-base) ease, backdrop-filter var(--duration-base) ease;
}

.site-header.scrolled {
  background: rgba(245, 242, 237, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.logo {
  font-family: var(--font-serif);
  font-size: var(--text-lg);
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.03em;
}

.logo span {
  color: var(--accent-terracotta);
}

.desktop-nav {
  display: none;
}

.desktop-nav a {
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--text-secondary);
  position: relative;
  padding-bottom: 2px;
  transition: color var(--duration-fast) ease;
}

.desktop-nav a::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text-primary);
  transition: width var(--duration-base) var(--ease-out-expo);
}

.desktop-nav a:hover {
  color: var(--text-primary);
}

.desktop-nav a:hover::after {
  width: 100%;
}

.desktop-nav a.active {
  color: var(--text-primary);
}

.desktop-nav a.active::after {
  width: 100%;
}

/* Mobile menu toggle */
.menu-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: var(--space-2);
  z-index: 110;
}

.menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text-primary);
  transition: transform var(--duration-base) var(--ease-out-expo), opacity var(--duration-base) ease;
}

.menu-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.menu-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* Mobile overlay nav */
.mobile-nav {
  position: fixed;
  inset: 0;
  z-index: 105;
  background: var(--bg-body);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--space-8);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--duration-slow) var(--ease-out-expo);
}

.mobile-nav.open {
  opacity: 1;
  pointer-events: all;
}

.mobile-nav a {
  font-family: var(--font-serif);
  font-size: var(--text-3xl);
  font-weight: 700;
  color: var(--text-primary);
  opacity: 0;
  transform: translateY(20px);
  transition: opacity var(--duration-slow) var(--ease-out-expo), transform var(--duration-slow) var(--ease-out-expo), color var(--duration-fast) ease;
}

.mobile-nav.open a {
  opacity: 1;
  transform: translateY(0);
}

.mobile-nav a:nth-child(1) { transition-delay: 80ms; }
.mobile-nav.open a:nth-child(1) { transition-delay: 80ms; }
.mobile-nav a:nth-child(2) { transition-delay: 160ms; }
.mobile-nav.open a:nth-child(2) { transition-delay: 160ms; }
.mobile-nav a:nth-child(3) { transition-delay: 240ms; }
.mobile-nav.open a:nth-child(3) { transition-delay: 240ms; }
.mobile-nav a:nth-child(4) { transition-delay: 320ms; }
.mobile-nav.open a:nth-child(4) { transition-delay: 320ms; }

.mobile-nav a:hover {
  color: var(--accent-terracotta);
}

/* ── 6. Marquee ───────────────────────────────────────────── */
.marquee-section {
  padding: var(--space-24) 0;
  overflow: hidden;
}

.marquee-row {
  display: flex;
  width: max-content;
  gap: var(--space-8);
  padding: var(--space-4) 0;
  will-change: transform;
}

.marquee-row span {
  font-family: var(--font-serif);
  font-size: var(--text-2xl);
  font-weight: 600;
  color: var(--text-primary);
  white-space: nowrap;
  opacity: 0.35;
  letter-spacing: -0.01em;
}

.marquee-row span.dot {
  opacity: 0.2;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-row.row-1 {
  animation: marquee-left 40s linear infinite;
}

.marquee-row.row-2 {
  animation: marquee-right 45s linear infinite;
}

.marquee-row.row-3 {
  animation: marquee-left 50s linear infinite;
}

/* ── 7. Media Showcase (Home) ─────────────────────────────── */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-4);
  padding: 0 var(--page-gutter) var(--space-16);
}

.media-showcase .media-block {
  aspect-ratio: 16 / 10;
  border-radius: 4px;
  overflow: hidden;
}

.media-showcase .media-block.terracotta {
  background: oklch(62% 0.12 50);
}

.media-showcase .media-block.sage {
  background: oklch(70% 0.07 145);
}

.media-showcase .media-block.sand {
  background: oklch(78% 0.09 80);
}

/* ── 8. Sections ──────────────────────────────────────────── */
.section {
  padding: var(--space-24) var(--page-gutter);
}

.section-label {
  font-family: var(--font-sans);
  font-size: var(--text-xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  margin-bottom: var(--space-6);
}

/* ── 9. Founder Letter (Editorial) ────────────────────────── */
.founder-letter {
  padding-top: calc(var(--space-32) + 60px);
  padding-bottom: var(--space-32);
}

.founder-letter .prose h2 {
  font-size: var(--text-2xl);
  margin-bottom: var(--space-8);
  line-height: 1.25;
}

.founder-letter .prose p {
  font-size: var(--text-lg);
  line-height: 1.8;
  margin-bottom: var(--space-6);
  color: var(--text-secondary);
}

.founder-letter .prose p:first-of-type::first-letter {
  font-family: var(--font-serif);
  font-size: 3.5em;
  float: left;
  line-height: 0.85;
  padding-right: var(--space-2);
  margin-top: 0.08em;
  color: var(--text-primary);
}

/* ── 10. Services ─────────────────────────────────────────── */
.philosophy-section {
  padding-top: calc(var(--space-24) + 60px);
}

.philosophy-heading {
  font-family: var(--font-serif);
  font-size: var(--text-3xl);
  font-weight: 700;
  margin-bottom: var(--space-8);
}

.philosophy-text {
  font-size: var(--text-lg);
  line-height: 1.75;
  max-width: 70ch;
}

.divider {
  height: 1px;
  background: var(--border-subtle);
  margin: var(--space-20) auto;
  max-width: var(--max-width);
  padding-inline: var(--page-gutter);
}

.service-item {
  margin-bottom: var(--space-16);
}

.service-item h3 {
  font-size: var(--text-xl);
  margin-bottom: var(--space-4);
}

.service-item p {
  font-size: var(--text-base);
  line-height: 1.7;
  max-width: 65ch;
}

/* ── 11. Clients Grid ─────────────────────────────────────── */
.clients-section {
  padding-top: calc(var(--space-24) + 60px);
}

.clients-heading {
  font-family: var(--font-serif);
  font-size: var(--text-3xl);
  font-weight: 700;
  margin-bottom: var(--space-16);
}

.clients-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-10);
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: var(--text-lg);
  font-weight: 700;
  margin-bottom: var(--space-2);
}

.client-card p {
  font-size: var(--text-sm);
  line-height: 1.6;
  color: var(--text-muted);
}

/* ── 12. Contact ──────────────────────────────────────────── */
.contact-section {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: var(--space-16) var(--page-gutter);
}

.contact-heading {
  font-family: var(--font-serif);
  font-size: var(--text-5xl);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-12);
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.contact-links a {
  font-family: var(--font-serif);
  font-size: var(--text-xl);
  font-weight: 600;
  color: var(--text-secondary);
  transition: color var(--duration-fast) ease;
}

.contact-links a:hover {
  color: var(--accent-terracotta);
}

/* ── 13. Footer ───────────────────────────────────────────── */
.site-footer {
  padding: var(--space-8) var(--page-gutter);
  text-align: center;
  border-top: 1px solid var(--border-subtle);
}

.site-footer p {
  font-size: var(--text-xs);
  color: var(--text-muted);
  letter-spacing: 0.05em;
}

/* ── 14. Responsive (Tablet + Desktop) ────────────────────── */
@media (min-width: 640px) {
  .media-showcase {
    grid-template-columns: repeat(3, 1fr);
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--space-12);
  }

  .contact-links {
    flex-direction: row;
    gap: var(--space-8);
  }
}

@media (min-width: 1024px) {
  .desktop-nav {
    display: flex;
    gap: var(--space-8);
  }

  .menu-toggle {
    display: none;
  }

  .mobile-nav {
    display: none !important;
  }

  .clients-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: var(--space-12) var(--space-8);
  }

  .founder-letter .prose h2 {
    font-size: var(--text-3xl);
  }
}

/* ── 15. Reduced Motion ───────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .marquee-row {
    animation: none !important;
  }

  html {
    scroll-behavior: auto;
  }

  .mobile-nav a {
    transition: none;
  }
}

