cd /app/output && python3 -c "
import re

files = ['index.html', 'neweno.html', 'services.html', 'clients.html', 'contact.html']
nav_links = ['index.html', 'neweno.html', 'services.html', 'clients.html', 'contact.html']

for f in files:
    with open(f, 'r') as file:
        content = file.read()
    print(f'=== {f} ===')
    # Check all nav links present
    for link in nav_links:
        if link in content:
            print(f'  OK: links to {link}')
        else:
            print(f'  MISSING: {link}')
    # Check styles.css linked
    if 'styles.css' in content:
        print('  OK: styles.css linked')
    else:
        print('  MISSING: styles.css')
    # Check Google Fonts
    if 'Playfair+Display' in content and 'Inter' in content:
        print('  OK: Google Fonts loaded')
    else:
        print('  MISSING: Google Fonts')
    # Check mobile menu toggle
    if 'menuToggle' in content:
        print('  OK: mobile menu toggle')
    else:
        print('  MISSING: mobile menu toggle')
    # Check mobile nav overlay
    if 'mobileNav' in content:
        print('  OK: mobile nav overlay')
    else:
        print('  MISSING: mobile nav overlay')
    print()
"
